head.script:
(function(){
  const XHTML_NS = "http://www.w3.org/1999/xhtml";
  const root = document.querySelector("foreignObject").firstElementChild;
  const head = root.querySelector("head");
  const body = root.querySelector("body");
  const originalCreateElement = document.createElement.bind(document);
  const originalCreateElementNS = document.createElementNS.bind(document);

  Object.defineProperty(document, "head", { get() { return head; }, configurable: true });
  Object.defineProperty(document, "body", { get() { return body; }, configurable: true });
  Object.defineProperty(document, "documentElement", { get() { return root; }, configurable: true });

  document.createElement = function(tagName, options) {
    if (typeof tagName === "string") {
      return originalCreateElementNS(XHTML_NS, tagName, options);
    }
    return originalCreateElement(tagName, options);
  };

  document.createElementNS = function(namespaceURI, qualifiedName, options) {
    if (namespaceURI == null || namespaceURI === XHTML_NS) {
      return originalCreateElementNS(XHTML_NS, qualifiedName, options);
    }
    return originalCreateElementNS(namespaceURI, qualifiedName, options);
  };
})();

body.script:
(async function() {
  const GITHUB_REPO = "athyx-network/Athyx-Network@main";
  const CDN_BASE = `https://cdn.jsdelivr.net/gh/${GITHUB_REPO}/`;
  const frame = document.getElementById('athyx-frame');
  const loader = document.getElementById('loader');

  function hideLoader() {
    if (loader) {
      loader.style.opacity = '0';
      setTimeout(() => loader.style.display = 'none', 300);
    }
  }

  frame.addEventListener('load', hideLoader);

  // Attempt 1: If hosted locally alongside index.html, load directly
  if (window.location.protocol.startsWith('http') && !window.location.hostname.includes('jsdelivr')) {
    const isLocalHost = window.location.pathname.endsWith('/app.svg');
    if (isLocalHost) {
      const basePath = window.location.pathname.replace(/[^/]*$/, '');
      frame.src = basePath + 'index.html';
      return;
    }
  }

  // Attempt 2: Standalone mode (loaded offline, from file://, or standalone) -> fetch via jsDelivr CDN
  try {
    const res = await fetch(CDN_BASE + 'index.html');
    if (!res.ok) throw new Error('CDN fetch failed: ' + res.status);
    let html = await res.text();

    // Inject <base> tag so all relative assets (themes.css, themes.js, pages, icons) load from jsDelivr CDN
    const baseTag = `<base href="${CDN_BASE}">`;
    if (html.includes('<head>')) {
      html = html.replace('<head>', '<head>' + baseTag);
    } else {
      html = baseTag + html;
    }

    frame.srcdoc = html;
  } catch (err) {
    console.warn('jsDelivr loader fallback to direct URL:', err);
    frame.src = CDN_BASE + 'index.html';
  }
})();
